try {
  const input = items[0].json;
  const results = [];

  if (input.chapters && Array.isArray(input.chapters)) {
    input.chapters.forEach((chapter, index) => {
      results.push({
        json: {
          page: index + 1,
          title: chapter.title,
          bullets: chapter.bullets || [], 
          image_description: chapter.image_description || "", 
          image_gen_prompt: chapter.image_gen_prompt || "", 
          image_drive_direct_url: chapter.image_drive_direct_url || "" 

        }
      });
    });
  } else {
    throw new Error("接收資料格式不符，請檢查 chapters 欄位");
  }

  return results;

} catch (error) {
  return [{ json: { status: "解析失敗", error: error.message } }];
}

const fs = require('fs');
const { execSync } = require('child_process');
const path = require('path');

const baseDir = 'C:\\n8n_tmp\\';
const marpExecutable = 'C:\\Users\\leejy\\AppData\\Roaming\\npm\\marp.cmd';
const edgePath = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';

try {
  // --- 【核心修正：跨節點抓取文字資料】 ---
  // 不管 OpenAI 給什麼，我們直接去問 Loop 節點現在跑的是哪一筆文字
  const loopItem = $node["Loop Over Items"].json; 

  // 從 Loop 資料裡精準抓取 page, title, bullets
  const pageNum = loopItem.page || 1; 
  const title = loopItem.title || "課程重點";
  let contentArray = (loopItem.bullets && Array.isArray(loopItem.bullets)) ? loopItem.bullets : ["無內容"];
  // ---------------------------------------

  const bulletMd = contentArray.map(b => `- ${b.trim()}`).join('\n');
  // --- 結束 ---

  const localImgName = `img_${pageNum}.png`;
  const localImgPath = path.join(baseDir, localImgName);
  let dataUri = "";

  const b64 = $input.item.json?.data?.[0]?.b64_json;
  if (b64) {
      if (!fs.existsSync(baseDir)) fs.mkdirSync(baseDir, { recursive: true });
      const buffer = Buffer.from(b64, 'base64');
      fs.writeFileSync(localImgPath, buffer);
      dataUri = `data:image/png;base64,${b64}`;
  }

  // 3. 組合 Markdown
  const marpContent = `---
marp: true
theme: gaia
style: |
  section {
    font-size: 23px; 
    background: #ffffff;
    color: #000000;
  }
  li {
    font-size: 20px; 
  }
---

# ${title}

${bulletMd}

${dataUri ? `![bg right:45% contain](${dataUri})` : ""}
`;

  const mdPath = path.join(baseDir, `p_${pageNum}.md`);
  const pngPath = path.join(baseDir, `r_${pageNum}.png`);

  fs.writeFileSync(mdPath, marpContent, 'utf8');

  // 4. 執行渲染
  execSync(`set "CHROME_PATH=${edgePath}" && "${marpExecutable}" "${mdPath}" --image png --output "${pngPath}" --no-sandbox --allow-local-files`);

  return [{
    json: { 
      status: "渲染成功", 
      page: pageNum, 
      realSize: dataUri.length, 
      path: pngPath 
    }
  }];

} catch (error) {
  return [{ json: { status: "渲染失敗", error: error.message } }];
}

