return items.map(item => {
  const bullets = item.json.bullets || [];

  const payload = {
    model: "gpt-4o-mini",
    response_format: { type: "json_object" },
    messages: [
      {
        role: "system",
        content: "你是投影片文字精簡助手。輸入是一組教學重點句子，請盡可能縮短縮短縮短句子，但是要保留所有重點，把每一句濃縮不超過23個中文字（或等長英文）的精簡句子，保留專有名詞，語意不失真，但要非常精煉，請力求圖片上文字完整部歪扭失真，且將圖片範圍鎖定在畫面正中間一個1024*1024的正方形框架中。用 JSON 回傳，格式為 {\"bullets\": [\"...\", \"...\"]}，數量要跟輸入一樣多，順序不變。"
      },
      {
        role: "user",
        content: JSON.stringify(bullets)
      }
    ]
  };

  return {
    json: {
      ...item.json,
      payload: payload
    }
  };
});

