const data = items[0].json; // 假設整個原始 JSON 放在前一個節點輸出的 json 裡
const slides = data.planned_slides;

const results = slides.map((s, index) => {
  // 這份資料 bullets 的位置在不同批次的檔案裡略有不同，這裡做個保險判斷
  let bullets = [];
  if (s.slide_content?.on_slide_content?.display_bullets) {
    bullets = s.slide_content.on_slide_content.display_bullets;
  } else if (Array.isArray(s.slide_content)) {
    bullets = s.slide_content;
  }

  const visualHint = s.slide_generation_instruction?.visual_plan
    || s.visual_design_instruction
    || s.layout_hint
    || "";

  return {
    json: {
      id: index + 1,
      title: s.title,
      start_time: s.source_start_time,
      bullets: bullets,
      visual_hint: visualHint // 先保留給下一步 LLM 當素材，最後輸出時可以拿掉
    }
  };
});

return results;

